-- =============================================================================================
-- Hand-written below this line: policies name a committee exactly when committee members
-- approve, one active policy per type and threshold; requests numbered per property, amounts in
-- the property's currency, the policy copied on and never changed afterwards; the requester
-- withdraws only while pending; decisions only on pending requests, never by the requester, once
-- per person, a reason to reject; the database settles the request (rejected at the first
-- rejection, approved at the required number of approvals). See docs/architecture/DATA_MODEL.md
-- section 11 (Approvals).
-- =============================================================================================

ALTER TABLE "approval_policies" ADD CONSTRAINT "approval_policies_shape"
  CHECK ("min_amount_minor" >= 0
         AND "required_approvals" BETWEEN 1 AND 10
         AND ("approvers" = 'COMMITTEE') = ("committee_id" IS NOT NULL));
CREATE UNIQUE INDEX "approval_policies_active_threshold"
  ON "approval_policies" ("property_id", "request_type", "min_amount_minor") WHERE "active";

CREATE FUNCTION app_approval_policy_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."committee_id" IS NOT NULL AND (TG_OP = 'INSERT' OR NEW."active") AND NOT EXISTS (
    SELECT 1 FROM "committees" WHERE "id" = NEW."committee_id" AND "status" = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'the committee is dissolved' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW."organisation_id", NEW."property_id", NEW."request_type", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."request_type", OLD."created_at") THEN
    RAISE EXCEPTION 'a policy keeps its property and request type' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "approval_policies_guard"
  BEFORE INSERT OR UPDATE ON "approval_policies"
  FOR EACH ROW EXECUTE FUNCTION app_approval_policy_guard();

ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_shape"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND "description" = btrim("description") AND length("description") BETWEEN 1 AND 4000
         AND ("amount_minor" IS NULL) = ("currency" IS NULL)
         AND ("amount_minor" IS NULL OR "amount_minor" > 0)
         AND "required_approvals" BETWEEN 1 AND 10
         AND ("approvers" = 'COMMITTEE') = ("committee_id" IS NOT NULL)
         AND "request_number" IS NOT NULL AND "request_number" >= 1
         AND ("status" IN ('APPROVED', 'REJECTED')) = ("decided_at" IS NOT NULL));

CREATE FUNCTION app_approval_request_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'PENDING' THEN
      RAISE EXCEPTION 'requests start pending' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."currency" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "properties" WHERE "id" = NEW."property_id" AND "currency" = NEW."currency"
    ) THEN
      RAISE EXCEPTION 'amounts are in the property''s currency' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."committee_id" IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM "committees" WHERE "id" = NEW."committee_id" AND "status" = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'the committee is dissolved' USING ERRCODE = 'check_violation';
    END IF;
    NEW."decided_at" := NULL;
    NEW."created_at" := now();
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.approval_requests:' || NEW."property_id"::text, 0));
    SELECT coalesce(max("request_number"), 0) + 1 INTO NEW."request_number"
      FROM "approval_requests" WHERE "property_id" = NEW."property_id";
    RETURN NEW;
  END IF;
  IF OLD."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'request % is settled', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."request_number", NEW."request_type", NEW."title", NEW."description",
      NEW."amount_minor", NEW."currency", NEW."document_id", NEW."policy_id", NEW."required_approvals", NEW."approvers",
      NEW."committee_id", NEW."requested_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."request_number", OLD."request_type", OLD."title", OLD."description",
      OLD."amount_minor", OLD."currency", OLD."document_id", OLD."policy_id", OLD."required_approvals", OLD."approvers",
      OLD."committee_id", OLD."requested_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'a request never changes; withdraw it and make a new one' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" IN ('APPROVED', 'REJECTED') THEN
    IF pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'requests are settled by their decisions' USING ERRCODE = 'insufficient_privilege';
    END IF;
    NEW."decided_at" := now();
  ELSIF NEW."status" = 'WITHDRAWN' AND app_current_user_id() IS DISTINCT FROM OLD."requested_by_user_id" THEN
    RAISE EXCEPTION 'only the requester withdraws a request' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "approval_requests_guard"
  BEFORE INSERT OR UPDATE ON "approval_requests"
  FOR EACH ROW EXECUTE FUNCTION app_approval_request_guard();

ALTER TABLE "approval_decisions" ADD CONSTRAINT "approval_decisions_note"
  CHECK (("note" IS NULL OR ("note" = btrim("note") AND length("note") BETWEEN 1 AND 1000))
         AND ("decision" = 'APPROVE' OR "note" IS NOT NULL));

CREATE FUNCTION app_approval_decision_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  r "approval_requests";
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'decisions are a permanent record' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM "approval_requests" WHERE "id" = NEW."request_id" FOR UPDATE;
  IF r."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'the request is settled' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."user_id" = r."requested_by_user_id" THEN
    RAISE EXCEPTION 'nobody decides their own request' USING ERRCODE = 'check_violation';
  END IF;
  IF app_current_user_id() IS DISTINCT FROM NEW."user_id" THEN
    RAISE EXCEPTION 'people record only their own decisions' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW."created_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "approval_decisions_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "approval_decisions"
  FOR EACH ROW EXECUTE FUNCTION app_approval_decision_guard();
CREATE TRIGGER "approval_decisions_no_truncate"
  BEFORE TRUNCATE ON "approval_decisions"
  FOR EACH STATEMENT EXECUTE FUNCTION app_approval_decision_guard();

CREATE FUNCTION app_approval_settle() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  approvals int;
BEGIN
  IF NEW."decision" = 'REJECT' THEN
    UPDATE "approval_requests" SET "status" = 'REJECTED' WHERE "id" = NEW."request_id";
  ELSE
    SELECT count(*) INTO approvals FROM "approval_decisions"
     WHERE "request_id" = NEW."request_id" AND "decision" = 'APPROVE';
    UPDATE "approval_requests" SET "status" = 'APPROVED'
     WHERE "id" = NEW."request_id" AND "required_approvals" <= approvals;
  END IF;
  RETURN NULL;
END
$$;

CREATE TRIGGER "approval_decisions_settle"
  AFTER INSERT ON "approval_decisions"
  FOR EACH ROW EXECUTE FUNCTION app_approval_settle();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['approval_policies', 'approval_requests', 'approval_decisions'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['approval_policies', 'approval_requests'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "approval_policies", "approval_requests", "approval_decisions" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "approval_policies", "approval_requests" TO veyra_app;
GRANT SELECT, INSERT ON "approval_decisions" TO veyra_app;
